import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"44、【姤】 巽下乾上","description":"周易口诀义 - 44、【姤】 巽下乾上","frontmatter":{"title":"44、【姤】 巽下乾上","description":"周易口诀义 - 44、【姤】 巽下乾上"},"headers":[],"relativePath":"zh/classics/koujueyi/046.md","filePath":"zh/classics/koujueyi/046.md"}'),r={name:"zh/classics/koujueyi/046.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_44、【姤】-巽下乾上" tabindex="-1">44、【姤】 巽下乾上 <a class="header-anchor" href="#_44、【姤】-巽下乾上" aria-label="Permalink to “44、【姤】 巽下乾上”">​</a></h1><p>彖曰：姤，遇也。柔遇刚也。「勿用取女」，不可与长也。天地相遇，品物咸章也。刚遇中正，天下大行也。姤之时义大矣哉！</p><p>象曰：天下有风，姤。后以施命诰四方。</p><p>初六：系于金柅，贞吉。有攸往，见凶。羸豕孚蹢躅。</p><p>象曰：「系于金柅」，柔道牵也。</p><p>九二：包有鱼，无咎。不利宾。</p><p>象曰：「包有鱼」，义不及宾也。</p><p>九三：臀无肤，其行次且，厉，无大咎。</p><p>象曰：「其行次且」，行未牵也。</p><p>九四：包无鱼，起凶。</p><p>象曰：「无鱼」之「凶」，远民也。</p><p>九五：以杞包瓜，含章，有陨自天。</p><p>象曰：九五「含章」，中正也。「有陨自天」，志不舍命也。</p><p>上九：姤其角，吝，无咎。</p><p>象曰：「姤其角」，上穷吝也。</p><p>解读</p><p>「姤，女壮，勿用取女」者，姤者，遇也。初六一柔而遇五刚，譬之人事，即是一女而遇五男。夫女之为道，固合婉娩贞顺，处于幽室，待礼乃行。今遇五男，淫壮若斯，故不可取，故曰「女壮，勿用取女」也。象曰：「天下有风，姤」者，风行天下，无物不遇，故是姤象也。「后以施命诰四方」者，后，君也；诰，诫也。风譬王者风教也，故风行草偃，所以人君象此，以施命诰戒于四方也。</p><p>初六，系于金柅，贞吉。有攸往，见凶。「羸豕孚蹢躅」者，金者，坚刚之物；柅者，制动之主，谓九四也。初六应在九四，若系于正应，制动由四，即合理之宜，正之吉矣，故曰「系于金柅，贞吉」也。然初六处遇之初，性又躁动，即是不牵系于四，而有所往，斯乃凶危立见，故曰「有攸往，见凶」。然淫躁若斯，又如羸弱之豕，蹢躅而进，故曰「羸豕乎蹢躅」也。羸豕，牝豕，为淫丑也。蹢躅，行不正貌。</p><p>「九二，包有鱼，无咎，不利宾」者，初六阴柔处下位，故称「鱼」也。初六与二相近，不能逆于所近，乐充九二之包厨，故曰「包有鱼」也。初自愿来，非己侵夺，故「无咎」也。擅人之物，以为己惠，故「不利宾」也。</p><p>「九三，臀无肤，其行次且，厉，无大咎」者，九三居下卦之上，是一卦之主，今初六与二相得，而九三失其所据，居即不安，行亦不进，故曰「臀无肤，其行次且」。然九三履得其位，非为妄处，直以不遇其时，故致危厉，灾非己招，故无大咎，故「厉无咎」也。</p><p>「九四，包无鱼，起凶」，初六与二相近，乐充九二之包厨，四失本应，故曰「包无鱼」。九四既失其应，即是下无民人，若无人而动，失应而作，有所兴为，即致凶灾，故曰「起凶」也。</p><p>「九五，以杞包瓜，含章，有陨自天」者，杞，枸杞也；瓜，瓠瓜也。杞生于肥地，瓠瓜为物，系而不食也。五居尊位，下无其应，犹如杞包瓜，系而不食，其犹人君虽居贵位，下既无人，何以施其教命？故曰「以杞包瓜」也。下无应援，教命不可行，虽有章美之德，而但包含之，故曰「含章」也。然以刚居尊，怀刚中之德，虽即教命不行，无人敢有倾陨矣。所有陨绝，惟天而已，故曰「有陨自天」也。</p><p>「上九：姤其角，吝，无咎」者，处遇之极，无所复遇，其犹一体之中遇角而已，故曰「姤其角」也。角既处上，即非所安，与不遇无异，故生悔吝。然下既无应，不与物竞，故无凶灾，故曰「吝无咎」也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
